// String describes the value with phone numbers masked and content shown as its length.
func (m BrandMessage) String() string {
	p := newPrinter("BrandMessage")
	p.value("sendType", m.SendType)
	p.value("msgType", m.MsgType)
	p.value("senderKey", m.SenderKey)
	p.value("templateCode", m.TemplateCode)
	p.value("targeting", m.Targeting)
	p.content("text", m.Text)
	p.value("header", m.Header)
	p.value("headerDescription", m.HeaderDescription)
	p.content("additionalContent", m.AdditionalContent)
	p.value("groupTagKey", m.GroupTagKey)
	p.value("adult", m.Adult)
	p.value("pushAlarm", m.PushAlarm)
	p.value("adFlag", m.AdFlag)
	p.keys("messageVariable", len(m.MessageVariable))
	p.keys("buttonVariable", len(m.ButtonVariable))
	p.keys("couponVariable", len(m.CouponVariable))
	p.keys("imageVariable", len(m.ImageVariable))
	p.keys("videoVariable", len(m.VideoVariable))
	p.keys("commerceVariable", len(m.CommerceVariable))
	p.value("carouselVariable", m.CarouselVariable)
	p.value("catalogVariable", m.CatalogVariable)
	p.phone("originCID", m.OriginCID)
	p.phone("unsubscribePhoneNumber", m.UnsubscribePhoneNumber)
	p.secret("unsubscribeAuthNumber", len(m.UnsubscribeAuthNumber) > 0)
	p.value("attachment", m.Attachment)
	p.value("carousel", m.Carousel)
	return p.String()
}

// GoString is String, so that %#v does not print phone numbers either.
func (m BrandMessage) GoString() string { return m.String() }

// LogValue is String, so that log/slog (also its JSON handler) logs the masked form.
func (m BrandMessage) LogValue() slog.Value { return slog.StringValue(m.String()) }

func (m *BrandMessage) validate(v *validator, path string) {
	if m.SendType == "" {
		v.required(joinPath(path, "sendType"))
	} else {
		v.enum(joinPath(path, "sendType"), m.SendType, "basic", "template", "free")
	}
	if m.SenderKey == "" {
		v.required(joinPath(path, "senderKey"))
	}
	if m.Targeting != "" {
		v.enum(joinPath(path, "targeting"), m.Targeting, "M", "N", "O", "I")
	}
	if m.Text != "" {
		v.maxLength(joinPath(path, "text"), m.Text, 1300)
	}
	if m.Header != "" {
		v.maxLength(joinPath(path, "header"), m.Header, 20)
	}
	if m.AdditionalContent != "" {
		v.maxLength(joinPath(path, "additionalContent"), m.AdditionalContent, 34)
	}
	if m.GroupTagKey != "" {
		v.maxLength(joinPath(path, "groupTagKey"), m.GroupTagKey, 40)
	}
	if m.Adult != "" {
		v.enum(joinPath(path, "adult"), m.Adult, "Y", "N")
	}
	if m.PushAlarm != "" {
		v.enum(joinPath(path, "pushAlarm"), m.PushAlarm, "Y", "N")
	}
	if m.AdFlag != "" {
		v.enum(joinPath(path, "adFlag"), m.AdFlag, "Y", "N")
	}
	for i := range m.CarouselVariable {
		m.CarouselVariable[i].validate(v, indexPath(joinPath(path, "carouselVariable"), i))
	}
	for i := range m.CatalogVariable {
		m.CatalogVariable[i].validate(v, indexPath(joinPath(path, "catalogVariable"), i))
	}
	if m.OriginCID != "" {
		v.maxLength(joinPath(path, "originCID"), m.OriginCID, 9)
	}
	if m.UnsubscribePhoneNumber != "" {
		v.maxLength(joinPath(path, "unsubscribePhoneNumber"), m.UnsubscribePhoneNumber, 13)
	}
	if m.UnsubscribeAuthNumber != "" {
		v.maxLength(joinPath(path, "unsubscribeAuthNumber"), m.UnsubscribeAuthNumber, 10)
	}
	if m.Attachment != nil {
		m.Attachment.validate(v, joinPath(path, "attachment"))
	}
	if m.Carousel != nil {
		m.Carousel.validate(v, joinPath(path, "carousel"))
	}
}

